export function writeSpacingArg(w: Writer, v: SpacingArg, t: Tables): void {
  void t;
  switch (v.t) {
    case "auto":
      w.u32(0);
      break;

    case "twips":
      w.u32(1);
      w.f64(v.v);
      break;

    default:
      throw new EncodeError(`"${String((v as { t: string }).t)}" is not a variant of SpacingArg`);

  }
}

export function readSpacingArg(r: Reader, t: Tables): SpacingArg {
  void t;
  const tag = r.u32();
  let out: SpacingArg;
  switch (tag) {
    case 0:
      out = { t: "auto" };
      break;

    case 1:
      out = { t: "twips", v: r.f64() };
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of SpacingArg`);

  }
  return out;
}

