/** `uo_docx::session::ops::styles::sheet::Ch<f64>` */
export type ChF64 =
  | { t: "keep" }
  | { t: "null" }
  | { t: "val"; v: number };


export function writeChF64(w: Writer, v: ChF64, t: Tables): void {
  void t;
  switch (v.t) {
    case "keep":
      w.u32(0);
      break;

    case "null":
      w.u32(1);
      break;

    case "val":
      w.u32(2);
      w.f64(v.v);
      break;

    default:
      throw new EncodeError(`"${String((v as { t: string }).t)}" is not a variant of ChF64`);

  }
}

export function readChF64(r: Reader, t: Tables): ChF64 {
  void t;
  const tag = r.u32();
  let out: ChF64;
  switch (tag) {
    case 0:
      out = { t: "keep" };
      break;

    case 1:
      out = { t: "null" };
      break;

    case 2:
      out = { t: "val", v: r.f64() };
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of ChF64`);

  }
  return out;
}

