export function writeChangeSet(w: Writer, v: ChangeSet, t: Tables): void {
  void t;
  w.bitmap([!!v.dirty, !!v.canUndo, !!v.canRedo, !!v.formatting]);
  w.len(v.stories.length);
  for (const e0 of v.stories) {
    writeCommandStoryChange(w, e0, t);
  }
  writeSelection(w, v.selection, t);
  w.len(v.events.length);
  for (const e0 of v.events) {
    writeEvent(w, e0, t);
  }
}

export function readChangeSet(r: Reader, t: Tables): ChangeSet {
  void t;
  const bm = r.bitmap(4);
  const f_stories = r.list(24, () => readCommandStoryChange(r, t));
  const f_selection = readSelection(r, t);
  const f_events = r.list(8, () => readEvent(r, t));
  const f_dirty = bitAt(bm, 0);
  const f_can_undo = bitAt(bm, 1);
  const f_can_redo = bitAt(bm, 2);
  const f_formatting = bitAt(bm, 3);
  const o: ChangeSet = { stories: f_stories, selection: f_selection, events: f_events, dirty: f_dirty, canUndo: f_can_undo, canRedo: f_can_redo, formatting: f_formatting };
  return o;
}

