export function readNullableBoxPicLine(r: Reader, t: Tables): NullableBoxPicLine {
  void t;
  const tag = r.u32();
  let out: NullableBoxPicLine;
  switch (tag) {
    case 0:
      out = { t: "null" };
      break;

    case 1:
      out = Object.assign(readPicLine(r, t), { t: "val" as const });
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of NullableBoxPicLine`);

  }
  return out;
}

