/** `uo_docx::read::watermark::WatermarkInfo` */
export type WatermarkInfo =
  | ({ t: "text" } & WatermarkTextInfo)
  | ({ t: "picture" } & WatermarkPictureInfo);


export function writeWatermarkInfo(w: Writer, v: WatermarkInfo, t: Tables): void {
  void t;
  switch (v.t) {
    case "text":
      w.u32(0);
      writeWatermarkTextInfo(w, v, t);
      break;

    case "picture":
      w.u32(1);
      writeWatermarkPictureInfo(w, v, t);
      break;

    default:
      throw new EncodeError(`"${String((v as { t: string }).t)}" is not a variant of WatermarkInfo`);

  }
}

export function readWatermarkInfo(r: Reader, t: Tables): WatermarkInfo {
  void t;
  const tag = r.u32();
  let out: WatermarkInfo;
  switch (tag) {
    case 0:
      out = Object.assign(readWatermarkTextInfo(r, t), { t: "text" as const });
      break;

    case 1:
      out = Object.assign(readWatermarkPictureInfo(r, t), { t: "picture" as const });
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of WatermarkInfo`);

  }
  return out;
}

