/** `uo_docx::session::ops::references::F10Result` */
export type F10Result =
  | { t: "unit" }
  | { t: "bool"; v: boolean }
  | { t: "count"; v: number }
  | ({ t: "hyphenation" } & OptManualHyphenation);


export function writeF10Result(w: Writer, v: F10Result, t: Tables): void {
  void t;
  switch (v.t) {
    case "unit":
      w.u32(0);
      break;

    case "bool":
      w.u32(1);
      w.bool(v.v);
      break;

    case "count":
      w.u32(2);
      w.u32(v.v);
      break;

    case "hyphenation":
      w.u32(3);
      writeOptManualHyphenation(w, v, t);
      break;

    default:
      throw new EncodeError(`"${String((v as { t: string }).t)}" is not a variant of F10Result`);

  }
}

export function readF10Result(r: Reader, t: Tables): F10Result {
  void t;
  const tag = r.u32();
  let out: F10Result;
  switch (tag) {
    case 0:
      out = { t: "unit" };
      break;

    case 1:
      out = { t: "bool", v: r.bool() };
      break;

    case 2:
      out = { t: "count", v: r.u32() };
      break;

    case 3:
      out = Object.assign(readOptManualHyphenation(r, t), { t: "hyphenation" as const });
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of F10Result`);

  }
  return out;
}

