/** What a decoder has received so far in one generation, and what an encoder keeps: the entries of every table (ids are positions). */
export interface Tables {
  generation: number | undefined;
}

export function newTables(): Tables {
  return { generation: undefined };
}

/** The number of entries of every table, in declaration order. */
export function tableLens(t: Tables): number[] {
  void t;
  return [];
}

/** The encoder's state: the tables (symbols are interned into them), how much of each was already sent, and the generation. */
export interface EncodeState {
  generation: number;
  tables: Tables;
  /** Per table, the entries before this index were sent by earlier messages. */
  sent: number[];
}

export function newEncodeState(generation: number, tables: Tables = newTables()): EncodeState {
  return { generation, tables, sent: new Array<number>(0).fill(0) };
}

/** Reads a `Exec` message. `tables` is the state of this stream of messages: the new entries are appended, a new generation replaces them, and an error leaves them as they were. */
export function decodeExec(buf: Uint8Array, tables: Tables, limits: Limits = DEFAULT_LIMITS): Exec {
  const r = new Reader(buf, limits);
  const head = r.header(MAGIC, SCHEMA_HASH);
  if (head.message !== MSG_EXEC) throw new DecodeError("WrongMessage", `message id ${head.message}, expected ${MSG_EXEC}`);
  const reset = tables.generation !== head.generation;
  const saved = reset ? { generation: tables.generation } : undefined;
  if (reset) Object.assign(tables, newTables());
  try {
    const msg = readExec(r, tables);
    r.end();
    tables.generation = head.generation;
    return msg;
  } catch (e) {
    if (saved) {
      Object.assign(tables, saved);
    }
    throw e;
  }
}

/** Writes a `Exec` message: the header, the new entries of every table (those past `state.sent`), the body. Symbols are interned into `state.tables`. */
export function encodeExec(msg: Exec, state: EncodeState): Uint8Array {
  const t = state.tables;
  const entries = new Writer();
  const body = new Writer();
  writeExec(body, msg, t);
  const w = new Writer();
  w.header(MAGIC, SCHEMA_HASH, MSG_EXEC, state.generation);
  w.raw(entries);
  w.raw(body);
  state.sent = tableLens(t);
  return w.finish();
}

